html:
{%- from "iso_compliance/templates/includes/en10204.html" import styles, head, products, results, statement, sign -%}
{#- EN 10204 type 2.2: test report, results of non-specific inspection. -#}
{%- set d = en10204(doc, "2.2") -%}
{{ styles() }}
<div class="rp">
{{ head(d) }}
{{ products(d) }}
{{ results(d) }}
{{ statement(d, "We hereby declare that the products supplied are in compliance with the requirements of the order. The test results given are based on non-specific inspection.") }}
{{ sign(d, "For " ~ d.company) }}
</div>
